// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        // Only test calls where there is at least one to address that is not the zero address
        // and caddress is a contract that can handle transferFrom
        vm.assume(_tos.length > 0);
        vm.assume(from != address(0));
        vm.assume(caddress != address(0) && caddress != address(c));
        // Ensure at least one to is non-zero
        bool hasNonZeroTo;
        for(uint i = 0; i < _tos.length; i++) {
            if(_tos[i] != address(0)) { hasNonZeroTo = true; break; }
        }
        vm.assume(hasNonZeroTo);
        // Deploy a simple contract that returns true on any call
        address target = address(new MockTarget());

        bool reverted;
        try c.transfer(from, target, _tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted, "transfer should not revert with valid inputs and a working target");
    }
}

contract MockTarget {
    fallback() external payable returns (bytes memory) {
        return abi.encode(true);
    }
}
